import {readFileSync,writeFileSync} from 'node:fs';
const read=p=>readFileSync(new URL(p,import.meta.url),'utf8');
const article=JSON.parse(read('./editorial/wegovy-cost-uk.json'));
article.path='/articles/'+article.slug;
const escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card='<article class="knowledge-card" data-babylove-article="wegovy-cost-uk" data-index="-1" data-kitem="" data-search="wegovy cost uk budgeting safe access support glp-1 article" data-title="'+escape(article.title)+'" data-topic="GLP-1" data-type="Article"><small>Article · Medicines &amp; treatment</small><h3>'+escape(article.title)+'</h3><p>'+escape(article.summary)+'</p><a href="'+article.path+'"><strong>Open →</strong></a></article>';
const assets=Object.fromEntries(article.publication_assets.map(a=>[a.public_path,read('../'+a.source)]));
const values={ARTICLE:article,MAIN:read('./editorial/article-main.html'),STYLES:'<style id="shift-article-layout">'+read('./editorial/article-layout.css')+'</style><style id="shift-article-contrast">'+read('./editorial/preview-contrast.css')+'</style>',ASSETS:assets,KNOWLEDGE_CARD:card};
writeFileSync(new URL('./editorial/public-bundle.mjs',import.meta.url),'// Generated by babylove/prepare-public-bundle.mjs from the approved article.\n'+Object.entries(values).map(([k,v])=>'export const '+k+'='+JSON.stringify(v)+';').join('\n')+'\n');
console.log('Prepared exact approved article, three images and Knowledge listing.');
